import re,math
from metrics import parse,value

def reconcile_temperatures(collect,policy):
    if not callable(collect)or type(policy)is not dict or set(policy)!={'physical_sensor','primary','secondary','tolerance_celsius'}:raise ValueError('approved sensor mapping required')
    if type(policy['physical_sensor'])is not str or not re.fullmatch(r'[A-Za-z0-9_.:-]{1,64}',policy['physical_sensor']):raise ValueError('bounded physical sensor identifier required')
    tolerance=policy['tolerance_celsius']
    if type(tolerance)not in(int,float)or not 0<=tolerance<=20 or not math.isfinite(tolerance):raise ValueError('bounded tolerance required')
    for key in ('primary','secondary'):
        selector=policy[key]
        if type(selector)is not dict or set(selector)!={'metric','labels'}or selector['metric']not in('node_thermal_zone_temp','node_hwmon_temp_celsius')or type(selector['labels'])is not dict or not selector['labels']or any(type(k)is not str or type(v)is not str for k,v in selector['labels'].items()):raise ValueError('exact native temperature selector required')
    if policy['primary']==policy['secondary']:raise ValueError('two distinct source selectors required')
    observation=collect()
    if type(observation)is not dict or set(observation)!={'status','body'}or type(observation['status'])is not int or observation['status']!=200 or type(observation['body'])is not str or len(observation['body'].encode())>1048576:raise ValueError('valid bounded native HTTP observation required')
    samples=parse(observation['body']);readings=[]
    for key in ('primary','secondary'):
        selector=policy[key];collector='thermal_zone'if selector['metric']=='node_thermal_zone_temp'else'hwmon'
        success=value(samples,'node_scrape_collector_success',{'collector':collector})
        item=value(samples,selector['metric'],selector['labels'])if success==1 else None
        if item is not None and not math.isfinite(item):raise ValueError('finite temperature required')
        readings.append(item)
    primary,secondary=readings
    if primary is None:raise ValueError('approved primary signal unavailable; no implicit failover')
    difference=None if secondary is None else abs(primary-secondary)
    return dict(schema=1,physical_sensor=policy['physical_sensor'],authoritative_celsius=primary,primary=policy['primary'],secondary_celsius=secondary,absolute_difference_celsius=difference,within_tolerance=None if difference is None else difference<=tolerance,aggregation='selected_primary_not_sum',scope='approved_mapping_not_inferred_hardware_identity')

